    return rows[0]["text"]

def extract(tree):
    rows = tree.where(content_desc="extension.active")
    if not rows:
        return False
    text = rows[0]["text"]
    return "active" in text.lower() and not bool(re.search(r"ends at\s+\d{1,2}:\d{2}", text, re.I))
